def keep_existing_reservations(apps, schema_editor):
    """Equipment already using non-home reservations (an upcoming marked slot) keeps the rules switched on."""
    import datetime

    Equipment = apps.get_model("equipment", "Equipment")
    DailySlot = apps.get_model("equipment", "DailySlot")
    ids = (
        DailySlot.objects.filter(home_department_only=True, date__gte=datetime.date.today())
        .values_list("slot_master__equipment_id", flat=True)
        .distinct()
    )
    Equipment.objects.filter(pk__in=list(ids), internal_department__isnull=False).update(
        department_slot_reservation_enabled=True
    )


# Initially on only for the Electronic Repair lab of the Institute Instrumentation Centre (IIC).
OIC_REGISTRATION_EQUIPMENT = (("ERL IIC", "IIC"),)


def enable_oic_registration_for_repair_lab(apps, schema_editor):
    Equipment = apps.get_model("equipment", "Equipment")
    for code, dept_code in OIC_REGISTRATION_EQUIPMENT:
        Equipment.objects.filter(code=code, internal_department__code=dept_code).update(
            oic_request_registration_enabled=True
        )


